import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, PlaneGeometry, Mesh } = ctx.THREE;

  // Root container
  const root = new Group();

  // ---------- Geometry ----------
  // Atlas region (fallback to full image if not provided)
  const atlasRect = (config.atlasRegion && config.atlasRegion.rect) || {
    x: 0,
    y: 0,
    width: 512,
    height: 320,
  };
  const aspect = atlasRect.width / atlasRect.height;
  const geometry = new PlaneGeometry(aspect, 1);

  // ---------- Material ----------
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;

  // Load texture (if any)
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      // Apply atlas UV offset / repeat
      const texW = tex.image?.width || atlasRect.width;
      const texH = tex.image?.height || atlasRect.height;

      const uScale = atlasRect.width / texW;
      const vScale = atlasRect.height / texH;

      tex.offset.set(atlasRect.x / texW, 1 - (atlasRect.y + atlasRect.height) / texH);
      tex.repeat.set(uScale, vScale);
      tex.needsUpdate = true;

      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // ---------- Mesh ----------
  const plane = new Mesh(geometry, material);
  // Billboard behavior: always face the camera
  plane.onBeforeRender = (renderer, scene, camera) => {
    plane.lookAt(camera.position);
  };
  root.add(plane);

  // ---------- Text ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 96,
      color: (config.colors?.paper) ?? '#e8ecf2',
      align: 'center',
    });
    // Position text slightly above the plane and a bit forward to avoid z‑fighting
    txt.position.set(0, 0.6, 0.01);
    root.add(txt);
  }

  // ---------- Cinematic Primitives ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      try {
        const handle = ctx.primitives[prim.name](root, prim.params);
        primitiveHandles.push(handle);
      } catch (e) {
        // Silently ignore missing primitive implementations
      }
    }
  }

  // ---------- Event Handlers Placeholder ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();

    // Dispose texture if it was set
    if (material.map) {
      material.map.dispose();
    }

    // Cleanup primitives
    for (const h of primitiveHandles) {
      if (h && typeof h.cleanup === 'function') {
        h.cleanup();
      }
    }

    // Kill any GSAP timelines that might have been created elsewhere
    gsap.globalTimeline.clear();

    // Dispose any child text objects
    root.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return root;
}
